import Foundation

/// 前線支援點位資料（應變中心 23 筆、救援單位 770 筆；救援單位原始 CSV 為 Big5/CP950）
struct FieldSupportSite: Identifiable, Hashable {
    enum Kind: String, CaseIterable, Hashable {
        case responseCenter = "應變中心"
        case rescueUnit = "救援單位"

        var label: String { L(rawValue) }
    }

    let id: String
    let kind: Kind
    let region: FieldHospital.Region
    let city: String
    let name: String
    let phone: String
    let address: String
    let longitude: Double?
    let latitude: Double?
    let note: String

    var hasCoordinate: Bool { longitude != nil && latitude != nil }

    var coordinateDescription: String? {
        guard let latitude, let longitude else { return nil }
        return String(format: "%.5f, %.5f", latitude, longitude)
    }

    var mapsURL: URL? {
        guard let latitude, let longitude else { return nil }
        var components = URLComponents(string: "http://maps.apple.com/")
        components?.queryItems = [
            URLQueryItem(name: "ll", value: "\(latitude),\(longitude)"),
            URLQueryItem(name: "q", value: name),
        ]
        return components?.url
    }
}

