    static var all: [FieldSupportSite] { responseCenters + rescueUnits }

    static func sites(for kind: FieldSupportSite.Kind) -> [FieldSupportSite] {
        switch kind {
        case .responseCenter: return responseCenters
        case .rescueUnit: return rescueUnits
        }
    }

    static func cities(kind: FieldSupportSite.Kind, region: FieldHospital.Region?) -> [String] {
        let source = sites(for: kind).filter { region == nil || $0.region == region }
        return Array(Set(source.map(\.city))).sorted()
    }

    static func grouped(kind: FieldSupportSite.Kind) -> [(region: FieldHospital.Region, items: [FieldSupportSite])] {
        let source = sites(for: kind)
        return FieldHospital.Region.allCases.compactMap { region in
            let items = source.filter { $0.region == region }
            return items.isEmpty ? nil : (region, items)
        }
    }
}
